// Adaptive midpoint integration with error control
double h = b - a;
double c = (a + b) / 2.0;
double fa = f(a);
double fb = f(b);
double fc = f(c);
double I = (h * fc);
double I_old = 0.0;
double error = std::numeric_limits<double>::max();

while (error > precision) {
    I_old = I;
    h /= 2.0;
    double c1 = (a + c) / 2.0;
    double c2 = (c + b) / 2.0;
    double fc1 = f(c1);
    double fc2 = f(c2);
    I = (h * (fc1 + fc2 + 4.0 * fc)) / 2.0;

    // Error estimation using the difference between current and previous approximation
    error = std::abs(I - I_old);
}

return I * m_sign;

